-- Production-derived API schema subset, captured 2026-10-26.

-- No production functions, triggers, grants, roles, or credentials are copied.

BEGIN;

CREATE TABLE public."countries" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "country_name" character varying(50) NOT NULL,
    "abbreviation" character varying(10) DEFAULT NULL::character varying,
    "iso_alpha_2" character varying(2) DEFAULT NULL::character varying,
    "tier1_warehouse_id" integer
);

CREATE TABLE public."regions" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "region_name" character varying(50) DEFAULT NULL::character varying,
    "country_id" integer NOT NULL,
    "abbreviation" character varying(45) DEFAULT NULL::character varying,
    "enabled" boolean DEFAULT true,
    "administrative_area" character varying(50) DEFAULT NULL::character varying
);

CREATE TABLE public."categories" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "parent_id" integer,
    "name" jsonb NOT NULL,
    "warranty_default" integer DEFAULT 12 NOT NULL,
    "parameter" jsonb,
    "priority" integer DEFAULT 100 NOT NULL
);

CREATE TABLE public."agents" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_login" character varying(20) NOT NULL,
    "user_password" character varying(20) NOT NULL,
    "tax_number" character varying(20) DEFAULT NULL::character varying,
    "contact_name" character varying(30) NOT NULL,
    "phone" character varying(50) DEFAULT NULL::character varying,
    "note" character varying(250) DEFAULT NULL::character varying,
    "commission" numeric(10,2) DEFAULT 0.00,
    "email" character varying(50) NOT NULL,
    "registration_date" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "parent_agent" integer DEFAULT 0,
    "master_agent" boolean DEFAULT false NOT NULL,
    "history_commissions" jsonb,
    "whatsapp" character varying(20) DEFAULT NULL::character varying,
    "teams" character varying(50) DEFAULT NULL::character varying
);

CREATE TABLE public."sales_channels" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "c_name" character varying(250) NOT NULL
);

CREATE TABLE public."payment_types" (
    "payment_type" character varying(50) NOT NULL PRIMARY KEY,
    "p_description" character varying(50) NOT NULL,
    "visible" boolean DEFAULT false NOT NULL
);

CREATE TABLE public."shop_groups" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "group_name" character varying(50) NOT NULL,
    "group_note" text,
    "sale_channel_id" integer
);

CREATE TABLE public."users" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "username" character varying(45) NOT NULL,
    "password" character varying(45) NOT NULL,
    "role" character varying(45) NOT NULL,
    "contact_info" jsonb,
    "tag" jsonb,
    "user_data" jsonb,
    "enabled" boolean DEFAULT true
);

CREATE TABLE public."customers" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "login" character varying(50) NOT NULL,
    "pass" character varying(50) NOT NULL,
    "business_name" character varying(120) DEFAULT NULL::character varying,
    "business_contact_name" character varying(100) DEFAULT NULL::character varying,
    "address_street" character varying(100) NOT NULL,
    "region_id" integer,
    "address_city" character varying(50) NOT NULL,
    "address_zip_code" character varying(50) DEFAULT NULL::character varying,
    "phone" character varying(50) DEFAULT NULL::character varying,
    "phone2" character varying(50) DEFAULT NULL::character varying,
    "website" character varying(100) DEFAULT NULL::character varying,
    "email" character varying(120) NOT NULL,
    "additional_emails" jsonb,
    "fiscal_code" character varying(20) DEFAULT NULL::character varying,
    "vat_country" character varying(2) DEFAULT NULL::character varying,
    "vat_number" character varying(20) DEFAULT NULL::character varying,
    "newsletter" boolean DEFAULT true,
    "reg_privacy" boolean,
    "reg_rules" boolean,
    "delivery_contact_name" character varying(100) DEFAULT NULL::character varying,
    "delivery_business_name" character varying(120) DEFAULT NULL::character varying,
    "delivery_address" character varying(100) DEFAULT NULL::character varying,
    "delivery_region_id" integer,
    "delivery_city" character varying(50) DEFAULT NULL::character varying,
    "delivery_zip_code" character varying(50) DEFAULT NULL::character varying,
    "delivery_phone" character varying(50) DEFAULT NULL::character varying,
    "preferred_categories" integer[],
    "registration_date" timestamp without time zone,
    "registration_ip" character varying(15) DEFAULT NULL::character varying,
    "payment_agreement" character varying(100) DEFAULT NULL::character varying,
    "preferred_payment_type" character varying(50) DEFAULT 'BONIFICO'::character varying,
    "preferred_language" character varying(50) DEFAULT NULL::character varying,
    "fido_granted" numeric(10,2) DEFAULT 0.00,
    "fido" numeric(10,2) DEFAULT 0.00,
    "payment_days" integer DEFAULT 0,
    "payment_days_eom" integer DEFAULT '-1'::integer,
    "tax2" numeric(18,2) DEFAULT 0.00,
    "shop_location_lat" numeric(18,10) DEFAULT NULL::numeric,
    "shop_location_lng" numeric(18,10) DEFAULT NULL::numeric,
    "verified" boolean DEFAULT false,
    "admin_note" character varying(250) DEFAULT NULL::character varying,
    "agent_id" integer DEFAULT 1,
    "payment_abi" character varying(5) DEFAULT NULL::character varying,
    "payment_cab" character varying(5) DEFAULT NULL::character varying,
    "payment_iban" character varying(34) DEFAULT NULL::character varying,
    "_notes" jsonb,
    "notes_open" integer DEFAULT 0 NOT NULL,
    "disable_box_discount" boolean DEFAULT false NOT NULL,
    "last_login_date" timestamp without time zone,
    "pec" character varying(100) DEFAULT NULL::character varying,
    "fiscal_agent_code" character varying(45) DEFAULT NULL::character varying,
    "disable_qty_delivery" boolean DEFAULT false,
    "rma_prepaid" boolean DEFAULT true,
    "disable_limit_sale" boolean DEFAULT false,
    "parameters" jsonb,
    "sales_channel_id" integer DEFAULT 1,
    "extra_data" jsonb,
    "shop_group_ids" integer[],
    "vies" boolean DEFAULT false NOT NULL
);

CREATE TABLE public."products" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "level_1" integer,
    "level_2" integer,
    "level_3" integer,
    "vendor_code" character varying(50) NOT NULL,
    "isin" character varying(30) NOT NULL,
    "qty_box" integer DEFAULT 1,
    "creation_date" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "featured" boolean DEFAULT false,
    "weight_gr" integer DEFAULT 0 NOT NULL,
    "dim_length_mm" integer,
    "dim_width_mm" integer,
    "dim_height_mm" integer,
    "owner_id" integer,
    "view" integer DEFAULT 0,
    "certificate" character varying(50),
    "color" character varying(50),
    "enabled" boolean DEFAULT false,
    "type1" character varying(50),
    "type2" character varying(50),
    "last_update" integer DEFAULT 0,
    "titles" jsonb,
    "descriptions" jsonb,
    "extra_specs" jsonb,
    "brand_id" integer,
    "excluded_countries" integer[] DEFAULT '{}'::integer[],
    "keywords" jsonb,
    "barcodes" jsonb DEFAULT '[]'::jsonb,
    "configurator_list" jsonb,
    "kit" boolean DEFAULT false NOT NULL
);

CREATE TABLE public."product_stocks" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "product_id" integer NOT NULL,
    "merchant_id" integer NOT NULL,
    "stock" integer DEFAULT 0 NOT NULL,
    "price_a" numeric(18,2) DEFAULT 0.00,
    "price_b" numeric(18,2) DEFAULT 0.00,
    "price_c" numeric(18,2) DEFAULT 0.00,
    "price_r" numeric(18,2) DEFAULT 0.00,
    "user_id" integer NOT NULL,
    "warehouse_id" integer NOT NULL,
    "last_supplier_id" integer,
    "location" character varying(100) DEFAULT NULL::character varying,
    "promotion_start" date,
    "promotion_end" date,
    "promo_price_a" numeric(18,2) DEFAULT NULL::numeric,
    "promo_price_b" numeric(18,2) DEFAULT NULL::numeric,
    "promo_price_c" numeric(18,2) DEFAULT NULL::numeric,
    "promo_price_r" numeric(18,2) DEFAULT NULL::numeric,
    "stock_alert" integer,
    "next_arrival_date" date,
    "invisible" boolean DEFAULT false NOT NULL,
    "tax_type" integer,
    "outlet" boolean DEFAULT false NOT NULL,
    "special_discount" smallint DEFAULT 0.00 NOT NULL,
    "limit_sale" jsonb,
    "last_out_of_stock" date,
    "warranty" smallint,
    "ps_excluded_countries" integer[] DEFAULT '{}'::integer[],
    "ps_dropshipping_available" boolean DEFAULT true NOT NULL,
    "warranty_note" character varying(1024),
    "qty_delivery" integer DEFAULT 1 NOT NULL,
    "per_box_discount" numeric(5,2) DEFAULT 0.00 NOT NULL,
    "delivery_weight_gr" integer,
    "sku" character varying(64),
    "creation_date" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "average_cost" numeric(18,2) DEFAULT 0.00,
    "temp_old_id" json,
    "moq" integer DEFAULT 1 NOT NULL,
    "warehouse_places_backup" jsonb,
    "warehouse_place_history" jsonb,
    "warehouse_note" character varying(250) DEFAULT NULL::character varying,
    "qty_box_wh" integer,
    "stock_note" character varying(250) DEFAULT NULL::character varying,
    "last_update" timestamp without time zone DEFAULT now() NOT NULL,
    "required_sn" boolean DEFAULT false NOT NULL
);

CREATE TABLE public."orders" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "customer_id" integer NOT NULL,
    "order_date" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "logistic_state" character varying(50) DEFAULT 'UNCONFIRMED'::character varying,
    "financial_state" character varying(50) DEFAULT 'UNPAID'::character varying,
    "delivery_cost" numeric(18,2) DEFAULT 0.00 NOT NULL,
    "note" character varying(250) DEFAULT NULL::character varying,
    "payment_type" character varying(50) DEFAULT NULL::character varying,
    "payment_parameter" jsonb,
    "tracking_url" character varying(250) DEFAULT NULL::character varying,
    "transport_doc_n" integer DEFAULT 99,
    "invoice_doc_n" integer DEFAULT 0,
    "transport_doc_date" date,
    "invoice_doc_date" date,
    "delivery_contact_name" character varying(100) DEFAULT NULL::character varying,
    "delivery_address" character varying(100) DEFAULT NULL::character varying,
    "delivery_region_id" integer,
    "delivery_city" character varying(50) DEFAULT NULL::character varying,
    "delivery_zip_code" character varying(50) DEFAULT NULL::character varying,
    "delivery_phone" character varying(50) DEFAULT NULL::character varying,
    "delivery_email" character varying(120) DEFAULT NULL::character varying,
    "business_name" character varying(120) DEFAULT NULL::character varying,
    "business_contact_name" character varying(100) DEFAULT NULL::character varying,
    "address_street" character varying(100) DEFAULT NULL::character varying,
    "region_id" integer,
    "address_city" character varying(50) DEFAULT NULL::character varying,
    "address_zip_code" character varying(50) DEFAULT NULL::character varying,
    "phone" character varying(50) DEFAULT NULL::character varying,
    "email" character varying(120) DEFAULT NULL::character varying,
    "fiscal_code" character varying(20) DEFAULT NULL::character varying,
    "vat_country" character varying(2) DEFAULT NULL::character varying,
    "vat_number" character varying(20) DEFAULT NULL::character varying,
    "delivery_business_name" character varying(120) DEFAULT NULL::character varying,
    "invoice_note" character varying(250) DEFAULT NULL::character varying,
    "td_note" character varying(250) DEFAULT NULL::character varying,
    "dropshipping" boolean DEFAULT false NOT NULL,
    "box_n" integer DEFAULT 0,
    "total" numeric(18,2) DEFAULT 0.00,
    "tax_type" integer,
    "tax2" numeric(10,2) DEFAULT NULL::numeric,
    "delivery_courier_id" integer,
    "invoice_state" character varying(32) DEFAULT 'VOID'::character varying,
    "stamp_duty" numeric(18,2) DEFAULT 0.00,
    "delivery_date" timestamp without time zone,
    "shipment_data" jsonb,
    "fulfillment_state" integer,
    "customer_reference" character varying(50) DEFAULT NULL::character varying,
    "edited" integer DEFAULT 0 NOT NULL,
    "imported_into" integer DEFAULT 0 NOT NULL,
    "attachment" jsonb,
    "order_info" jsonb,
    "temp_old_id" json,
    "merchant_vat_number" character varying(20)
);

CREATE TABLE public."order_details" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "product_stock_id" integer NOT NULL,
    "qty" integer NOT NULL,
    "price" numeric(18,2) DEFAULT 0.00 NOT NULL,
    "order_id" integer NOT NULL,
    "tax_type" integer NOT NULL,
    "perbox_discount" numeric(18,2) DEFAULT 0.00 NOT NULL,
    "qty_box" integer DEFAULT 1 NOT NULL,
    "rma_qty" integer DEFAULT 0 NOT NULL,
    "rma_warranty" integer DEFAULT 0 NOT NULL,
    "product_description" character varying(100) NOT NULL,
    "price_r" numeric(18,2) DEFAULT NULL::numeric,
    "warehouse_id" integer,
    "row_discount" numeric(18,2) DEFAULT 0.00 NOT NULL,
    "extra_data" jsonb
);

ALTER TABLE public.users ADD UNIQUE (username);

ALTER TABLE public.customers ADD UNIQUE (login);

ALTER TABLE public.regions ADD FOREIGN KEY (country_id) REFERENCES public.countries(id);

ALTER TABLE public.customers ADD FOREIGN KEY (region_id) REFERENCES public.regions(id);

ALTER TABLE public.customers ADD FOREIGN KEY (delivery_region_id) REFERENCES public.regions(id);

ALTER TABLE public.customers ADD FOREIGN KEY (agent_id) REFERENCES public.agents(id);

ALTER TABLE public.customers ADD FOREIGN KEY (sales_channel_id) REFERENCES public.sales_channels(id);

ALTER TABLE public.customers ADD FOREIGN KEY (preferred_payment_type) REFERENCES public.payment_types(payment_type);

ALTER TABLE public.products ADD FOREIGN KEY (owner_id) REFERENCES public.users(id);

ALTER TABLE public.product_stocks ADD FOREIGN KEY (product_id) REFERENCES public.products(id);

ALTER TABLE public.product_stocks ADD FOREIGN KEY (user_id) REFERENCES public.users(id);

ALTER TABLE public.orders ADD FOREIGN KEY (customer_id) REFERENCES public.customers(id);

ALTER TABLE public.order_details ADD FOREIGN KEY (order_id) REFERENCES public.orders(id);

ALTER TABLE public.order_details ADD FOREIGN KEY (product_stock_id) REFERENCES public.product_stocks(id);

COMMIT;
